import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { useProgramData } from '../lib/useProgramData';
import CustomSelect from './CustomSelect';
import { AssignmentHistory, ParticipantLists } from '../lib/types';

declare const html2pdf: any;

const buildPrintableHTML = (programs: any[]) => {
    const safe = (v: any) => (v == null ? '' : String(v));
    const formatPair = (str: string | null | undefined): string => {
        if (!str) return '';
        const parts = str.split('/').map(s => s.trim()).filter(Boolean);
        if (parts.length > 1) {
            return `${parts[0]} /<br>${parts[1]}`;
        }
        return parts[0] || '';
    };

    const pages: any[][] = [];
    for (let i = 0; i < programs.length; i += 2) {
        pages.push(programs.slice(i, i + 2));
    }

    const pagesHTML = pages.map(pagePrograms => {
        const pageContentHTML = pagePrograms.map((program, idx) => {
            const data = program.data || {};
            const title = safe(data.titulo) || `Programa ${program.week_id || ''}`;
            const canciones = data.canciones || {};
            const rooms = ["Sala Auxiliar N°3", "Sala Auxiliar N°2", "Auditorio principal"];
            const watermarkText = data.watermark ?? 'PRELIMINAR';
            const isBlurred = data.isBlurred ?? false;

            return `
                <div class="printable-program ${isBlurred ? 'blurred' : ''}" data-watermark="${watermarkText}">
                    <table class="print-table">
                        <colgroup>
                            <col class="col-parte">
                            <col class="col-sala">
                            <col class="col-sala">
                            <col class="col-sala">
                        </colgroup>
                        <thead>
                            <tr><th colspan="4" class="print-title">${title}</th></tr>
                            <tr>
                                <th></th>
                                <th>${rooms[0]}</th>
                                <th>${rooms[1]}</th>
                                <th>${rooms[2]}</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr><td><strong>Presidente:</strong></td><td class="participante">${safe(data.presidentes?.aux3)}</td><td class="participante">${safe(data.presidentes?.aux2)}</td><td class="participante">${safe(data.presidentes?.principal)}</td></tr>
                            <tr><td><strong>Oración de Inicio:</strong></td><td></td><td></td><td class="participante">${safe(data.oracion?.inicio)}</td></tr>
                            <tr><td>• <b>${safe(canciones.inicio)}</b></td><td></td><td></td><td></td></tr>
                            <tr><td>• Palabras de introducción (1 min.)</td><td></td><td></td><td></td></tr>
                            <tr class="section tesoros"><td colspan="4">TESOROS DE LA BIBLIA</td></tr>
                            <tr><td>${safe(data.tesoros?.p1?.title)}</td><td></td><td></td><td class="participante">${safe(data.tesoros?.p1?.main)}</td></tr>
                            <tr><td>${safe(data.tesoros?.p2?.title)}</td><td></td><td></td><td class="participante">${safe(data.tesoros?.p2?.main)}</td></tr>
                            <tr><td>${safe(data.tesoros?.p3?.title) || '3. Lectura de la Biblia (3 min.)'}</td><td class="participante">${safe(data.tesoros?.p3?.aux3)}</td><td class="participante">${safe(data.tesoros?.p3?.aux2)}</td><td class="participante">${safe(data.tesoros?.p3?.main)}</td></tr>
                            <tr class="section maestros"><td colspan="4">SEAMOS MEJORES MAESTROS</td></tr>
                            ${(data.maestros || []).map((m: any) => `
                                <tr>
                                    <td>${safe(m.title)}</td>
                                    <td class="participante">${formatPair(m.aux3)}</td>
                                    <td class="participante">${formatPair(m.aux2)}</td>
                                    <td class="participante">${formatPair(m.main)}</td>
                                </tr>
                            `).join('')}
                            <tr class="section vida-cristiana"><td colspan="4">NUESTRA VIDA CRISTIANA</td></tr>
                            <tr><td>• <b>${safe(canciones.vidaCristiana)}</b></td><td></td><td></td><td></td></tr>
                            ${(data.vidaCristiana || []).map((v: any) => {
                                let participantDetail = '';
                                if (v.hasOwnProperty('conductor')) {
                                    participantDetail = safe(v.conductor);
                                    if (v.lector) {
                                        participantDetail += `<br>Lector: ${safe(v.lector)}`;
                                    }
                                } else if (v.hasOwnProperty('discursante')) {
                                    participantDetail = safe(v.discursante);
                                }
                                return `
                                    <tr>
                                        <td>• ${safe(v.titulo)}</td>
                                        <td></td>
                                        <td></td>
                                        <td class="participante">${participantDetail}</td>
                                    </tr>
                                `;
                            }).join('')}
                            <tr><td>• Palabras de conclusión (3 mins.)</td><td></td><td></td><td></td></tr>
                            <tr><td>• <b>${safe(canciones.final)}</b></td><td></td><td></td><td></td></tr>
                            <tr><td><strong>Oración Final:</strong></td><td></td><td></td><td class="participante">${safe(data.oracion?.final)}</td></tr>
                        </tbody>
                    </table>
                </div>
                ${idx === 0 && pagePrograms.length > 1 ? '<div class="page-divider"></div>' : ''}
            `;
        }).join('');

        return `<div class="print-page">${pageContentHTML}</div>`;
    }).join('');

    const styles = `
        <style>
            @media print { 
                @page { size: A4 portrait; margin: 0; } 
                body { padding: 0; font-size: 9pt; -webkit-print-color-adjust: exact !important; color-adjust: exact !important; } 
                .no-print { display: none !important; }
            }
            body { font-family: "Arial", sans-serif; margin: 0; padding: 0; color: #111; background-color: #fff; }
            .print-actions { position: sticky; top: 0; background-color: #f8f9fa; z-index: 100; padding: 10px; border-bottom: 1px solid #ddd; display:flex; gap:10px; align-items:center; justify-content:center; }
            .print-actions button { font-size: 0.9em; padding: 8px 16px; border: 1px solid #ccc; border-radius: 6px; cursor: pointer; background:#fff; font-weight: bold; }
            .print-actions button.primary { background: #007bff; color: #fff; border-color: #0056b3; }

            #print-container { width: 210mm; margin: 0 auto; background-color: #fff; }

            .print-page {
                width: 210mm;
                height: 297mm;
                padding: 10mm;
                box-sizing: border-box;
                display: flex;
                flex-direction: column;
                page-break-after: always;
                position: relative;
            }
            .print-page:last-child { page-break-after: auto; }

            .printable-program { 
                height: 135mm; /* A bit less than half to allow for gap and margins */
                overflow: hidden;
                display: flex;
                flex-direction: column;
                position: relative;
                box-sizing: border-box;
            }

            .page-divider {
                height: 1mm;
                border-top: 1px dashed #ccc;
                margin: 5mm 0;
                width: 100%;
            }

            .print-table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 8.5pt; border: 1px solid #000; }
            .print-title { font-size: 13pt; font-weight: 800; padding: 4px; border-bottom: 1px solid #000; }
            .print-table th, .print-table td { padding: 2px 4px; vertical-align: middle; line-height: 1.1; border: 1px solid #000; text-align: left; }
            .print-table th { text-align: center; font-weight: 700; font-size: 9pt; background-color: #f2f2f2; }
            .print-table td.participante { text-align: center; }
            .col-parte { width: 40%; }
            .col-sala { width: 20%; }
            .section td { font-weight: 900; text-transform: uppercase; color: #fff; padding: 4px 8px; text-align: center !important; font-size: 9.5pt; border: 1px solid #000 !important; }
            .section.tesoros td { background-color: #5a6369 !important; }
            .section.maestros td { background-color: #c19a26 !important; }
            .section.vida-cristiana td { background-color: #8b2c39 !important; }

            .printable-program.blurred { position: relative; }
            .printable-program.blurred::before { 
                content: attr(data-watermark); 
                position: absolute; 
                top: 50%; 
                left: 50%; 
                transform: translate(-50%, -50%) rotate(-45deg); 
                font-size: 5em; 
                color: rgba(0,0,0,0.15); 
                font-weight: bold; 
                pointer-events: none; 
                z-index: 1000; 
                white-space: nowrap;
            }
            .printable-program.blurred .print-table { filter: blur(3px); }
        </style>
    `;

    return `
        <!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Programa VMT - Impresión</title>${styles}</head><body>
            <div class="print-actions no-print">
                <button class="primary" onclick="window.print()">Imprimir Todo</button>
                <button onclick="window.close()">Cerrar Ventana</button>
            </div>
            <div id="print-container">${pagesHTML}</div>
        </body></html>
    `;
};


const roomMap: { [key: string]: string } = {
    main: 'Auditorio Principal',
    aux2: 'Sala Auxiliar 2',
    aux3: 'Sala Auxiliar 3'
};

const MobileAssignmentRow: React.FC<{ label: string; children: React.ReactNode; isInline?: boolean }> = ({ label, children, isInline }) => (
    <div className={`mobile-assignment-row ${isInline ? 'mobile-assignment-row--inline' : ''}`}>
        <div className="mobile-assignment-label">{label}</div>
        <div className="mobile-assignment-participant">{children}</div>
    </div>
);

const MobileProgramView: React.FC<{
    programData: any;
    getValue: (path: string) => any;
    handleDataChange: (weekId: string, path: string, value: string | boolean) => void;
    lists: ParticipantLists;
    history: AssignmentHistory;
    selectedWeek: string;
}> = ({ programData, getValue, handleDataChange, lists, history, selectedWeek }) => {
    const [activeMobileTab, setActiveMobileTab] = useState('general');

    if (!programData) return null;

    const renderMaestrosParticipant = (part: any, index: number, room: 'main' | 'aux2' | 'aux3') => {
        const path = `maestros.${index}.${room}`;
        const assignmentValue = getValue(path) || '';
        const isDiscurso = part.title?.toLowerCase().includes('discurso');

        if (isDiscurso) {
            return <CustomSelect options={lists['maestros_discurso'] || []} value={assignmentValue} onChange={val => handleDataChange(selectedWeek, path, val)} historyProvider={history} />;
        }

        const [enc, ayu] = (assignmentValue || '').split('/').map((s: string) => s.trim());
        return (
            <div className="mobile-participant-pair-wrapper">
                <div className="mobile-participant-pair">
                    <span className="mobile-participant-pair__label">Enc.</span>
                    <div className="mobile-participant-pair__select">
                        <CustomSelect options={lists['publicadores'] || []} value={enc || ''} onChange={val => handleDataChange(selectedWeek, path, `${val} / ${ayu||''}`.trim())} historyProvider={history} />
                    </div>
                </div>
                <div className="mobile-participant-pair">
                    <span className="mobile-participant-pair__label">Ayu.</span>
                    <div className="mobile-participant-pair__select">
                        <CustomSelect options={lists['publicadores'] || []} value={ayu || ''} onChange={val => handleDataChange(selectedWeek, path, `${enc||''} / ${val}`.trim())} historyProvider={history} />
                    </div>
                </div>
            </div>
        );
    };

    const renderGeneralTab = () => (
        <div className="mobile-card">
            <div className="mobile-card__header vida-cristiana-header">Información General</div>
            <div className="mobile-card__body">
                <MobileAssignmentRow label="Presidente (Principal)"><CustomSelect options={lists['presidentes'] || []} value={getValue('presidentes.principal') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.principal', val)} historyProvider={history} /></MobileAssignmentRow>
                <MobileAssignmentRow label="Presidente (Sala 2)"><CustomSelect options={lists['consejeros'] || []} value={getValue('presidentes.aux2') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.aux2', val)} historyProvider={history} /></MobileAssignmentRow>
                <MobileAssignmentRow label="Presidente (Sala 3)"><CustomSelect options={lists['consejeros'] || []} value={getValue('presidentes.aux3') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.aux3', val)} historyProvider={history} /></MobileAssignmentRow>
                <MobileAssignmentRow label="Oración de Inicio"><CustomSelect options={lists['oradores'] || []} value={getValue('oracion.inicio') || ''} onChange={val => handleDataChange(selectedWeek, 'oracion.inicio', val)} historyProvider={history} /></MobileAssignmentRow>
                <MobileAssignmentRow label="Oración Final"><CustomSelect options={lists['oradores'] || []} value={getValue('oracion.final') || ''} onChange={val => handleDataChange(selectedWeek, 'oracion.final', val)} historyProvider={history} /></MobileAssignmentRow>
            </div>
        </div>
    );

    const renderTesorosTab = () => (
         <div className="mobile-card">
            <div className="mobile-card__header tesoros-header">Tesoros de la Biblia</div>
            <div className="mobile-card__body">
                <MobileAssignmentRow label={getValue('tesoros.p1.title') || 'Discurso'}><CustomSelect options={lists['discursantes'] || []} value={getValue('tesoros.p1.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p1.main', val)} historyProvider={history} /></MobileAssignmentRow>
                <MobileAssignmentRow label={getValue('tesoros.p2.title') || 'Perlas Escondidas'}><CustomSelect options={lists['discursantes'] || []} value={getValue('tesoros.p2.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p2.main', val)} historyProvider={history} /></MobileAssignmentRow>
                <MobileAssignmentRow label={getValue('tesoros.p3.title') || '3. Lectura de la Biblia (3 min.)'}>
                    <div className="room-participants">
                        <div className="mobile-participant-pair"><span className="mobile-participant-pair__label">{roomMap.main}</span><div className="mobile-participant-pair__select"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.main', val)} historyProvider={history} /></div></div>
                        <div className="mobile-participant-pair"><span className="mobile-participant-pair__label">{roomMap.aux2}</span><div className="mobile-participant-pair__select"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.aux2') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.aux2', val)} historyProvider={history} /></div></div>
                        <div className="mobile-participant-pair"><span className="mobile-participant-pair__label">{roomMap.aux3}</span><div className="mobile-participant-pair__select"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.aux3') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.aux3', val)} historyProvider={history} /></div></div>
                    </div>
                </MobileAssignmentRow>
            </div>
        </div>
    );

    const renderMaestrosTab = () => (
        <div className="mobile-card">
            <div className="mobile-card__header maestros-header">Seamos Mejores Maestros</div>
            <div className="mobile-card__body">
                {(getValue('maestros') || []).map((part: any, i: number) => (
                    <div className="assignment-group" key={`maestros-mob-${i}`}>
                        <h4 className="assignment-group__title">{part.title}</h4>
                        <div className="assignment-group__rooms">
                            <div className="room-participants"><div className="room-label">{roomMap.main}</div>{renderMaestrosParticipant(part, i, 'main')}</div>
                            <div className="room-participants"><div className="room-label">{roomMap.aux2}</div>{renderMaestrosParticipant(part, i, 'aux2')}</div>
                            <div className="room-participants"><div className="room-label">{roomMap.aux3}</div>{renderMaestrosParticipant(part, i, 'aux3')}</div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );

    const renderVidaCristianaTab = () => (
        <div className="mobile-card">
            <div className="mobile-card__header vida-cristiana-header">Nuestra Vida Cristiana</div>
            <div className="mobile-card__body">
                {(getValue('vidaCristiana') || []).map((part: any, i: number) => {
                    const pathPrefix = `vidaCristiana.${i}`;
                    if (part.hasOwnProperty('discursante')) {
                        return (<MobileAssignmentRow key={pathPrefix} label={part.titulo}><CustomSelect options={lists['discursantes'] || []} value={getValue(`${pathPrefix}.discursante`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.discursante`, val)} historyProvider={history} /></MobileAssignmentRow>);
                    }
                    if (part.hasOwnProperty('conductor')) {
                            return (
                            <div key={pathPrefix}>
                                <MobileAssignmentRow label={`${part.titulo} (Conductor)`}><CustomSelect options={lists['discursantes'] || []} value={getValue(`${pathPrefix}.conductor`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.conductor`, val)} historyProvider={history} /></MobileAssignmentRow>
                                {part.hasOwnProperty('lector') && (<MobileAssignmentRow label={`${part.titulo} (Lector)`}><CustomSelect options={lists['lectores_libro'] || []} value={getValue(`${pathPrefix}.lector`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.lector`, val)} historyProvider={history} /></MobileAssignmentRow>)}
                            </div>
                        );
                    }
                    return null;
                })}
            </div>
        </div>
    );

    return (
        <div className="programa-mobile-view">
             <nav className="mobile-tabs-nav">
                <button onClick={() => setActiveMobileTab('general')} className={activeMobileTab === 'general' ? 'active' : ''}>General</button>
                <button onClick={() => setActiveMobileTab('tesoros')} className={activeMobileTab === 'tesoros' ? 'active' : ''}>Tesoros</button>
                <button onClick={() => setActiveMobileTab('maestros')} className={activeMobileTab === 'maestros' ? 'active' : ''}>Maestros</button>
                <button onClick={() => setActiveMobileTab('vida')} className={activeMobileTab === 'vida' ? 'active' : ''}>Vida Cristiana</button>
            </nav>
            <div className="mobile-tabs-content">
                {activeMobileTab === 'general' && renderGeneralTab()}
                {activeMobileTab === 'tesoros' && renderTesorosTab()}
                {activeMobileTab === 'maestros' && renderMaestrosTab()}
                {activeMobileTab === 'vida' && renderVidaCristianaTab()}
            </div>
        </div>
    );
};

const DesktopProgramView: React.FC<{
    programData: any;
    getValue: (path: string) => any;
    handleDataChange: (weekId: string, path: string, value: string | boolean) => void;
    lists: ParticipantLists;
    history: AssignmentHistory;
    selectedWeek: string;
}> = ({ programData, getValue, handleDataChange, lists, history, selectedWeek }) => {
     if (!programData) return null;
    return (
        <div className="programa-desktop-view">
             <table className="main-program-table">
                <tbody>
                    <tr><td><strong>Presidente:</strong></td>
                        <td><CustomSelect options={lists['consejeros'] || []} value={getValue('presidentes.aux3') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.aux3', val)} historyProvider={history} /></td>
                        <td><CustomSelect options={lists['consejeros'] || []} value={getValue('presidentes.aux2') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.aux2', val)} historyProvider={history} /></td>
                        <td><CustomSelect options={lists['presidentes'] || []} value={getValue('presidentes.principal') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.principal', val)} historyProvider={history} /></td>
                    </tr>
                    <tr><td><strong>Oración de Inicio:</strong></td><td></td><td></td><td><CustomSelect options={lists['oradores'] || []} value={getValue('oracion.inicio') || ''} onChange={val => handleDataChange(selectedWeek, 'oracion.inicio', val)} historyProvider={history} /></td></tr>

                    <tr className="section tesoros"><td colSpan={4} className="section-header">Tesoros de la Biblia</td></tr>
                    <tr><td>{getValue('tesoros.p1.title')}</td><td></td><td></td><td><CustomSelect options={lists['discursantes'] || []} value={getValue('tesoros.p1.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p1.main', val)} historyProvider={history} /></td></tr>
                    <tr><td>{getValue('tesoros.p2.title')}</td><td></td><td></td><td><CustomSelect options={lists['discursantes'] || []} value={getValue('tesoros.p2.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p2.main', val)} historyProvider={history} /></td></tr>
                    <tr><td>{getValue('tesoros.p3.title') || '3. Lectura de la Biblia (3 min.)'}</td>
                        <td><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.aux3') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.aux3', val)} historyProvider={history} /></td>
                        <td><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.aux2') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.aux2', val)} historyProvider={history} /></td>
                        <td><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.main', val)} historyProvider={history} /></td>
                    </tr>
                    <tr className="section maestros"><td colSpan={4} className="section-header">Seamos Mejores Maestros</td></tr>
                     {(getValue('maestros') || []).map((part: any, i: number) => {
                         const isDiscurso = part.title?.toLowerCase().includes('discurso');
                         return (
                            <tr key={`maestros-desk-${i}`}>
                                <td>{part.title}</td>
                                 {(['aux3', 'aux2', 'main']).map(room => {
                                    const path = `maestros.${i}.${room}`;
                                    const assignmentValue = getValue(path) || '';
                                    if(isDiscurso) {
                                        return <td key={room}><CustomSelect options={lists['maestros_discurso'] || []} value={assignmentValue} onChange={val => handleDataChange(selectedWeek, path, val)} historyProvider={history} /></td>
                                    }
                                    const [enc, ayu] = assignmentValue.split('/').map((s: string) => s.trim());
                                    return (
                                        <td key={room}>
                                            <div className="role-participant-box">
                                                <div className="role-label">Enc:</div>
                                                <CustomSelect options={lists['publicadores'] || []} value={enc || ''} onChange={val => handleDataChange(selectedWeek, path, `${val} / ${ayu||''}`.trim())} historyProvider={history} />
                                            </div>
                                             <div className="role-participant-box" style={{marginTop: '8px'}}>
                                                <div className="role-label">Ayu:</div>
                                                <CustomSelect options={lists['publicadores'] || []} value={ayu || ''} onChange={val => handleDataChange(selectedWeek, path, `${enc||''} / ${val}`.trim())} historyProvider={history} />
                                            </div>
                                        </td>
                                    )
                                 })}
                            </tr>
                         )
                     })}

                    <tr className="section vida-cristiana"><td colSpan={4} className="section-header">Nuestra Vida Cristiana</td></tr>
                    {(getValue('vidaCristiana') || []).map((part: any, i: number) => {
                         const pathPrefix = `vidaCristiana.${i}`;
                         if (part.hasOwnProperty('discursante')) {
                            return (<tr key={pathPrefix}><td>{part.titulo}</td><td></td><td></td><td><CustomSelect options={lists['discursantes'] || []} value={getValue(`${pathPrefix}.discursante`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.discursante`, val)} historyProvider={history} /></td></tr>);
                        }
                        if (part.hasOwnProperty('conductor')) {
                             return (
                                <tr key={pathPrefix}><td>{part.titulo}</td><td></td><td></td>
                                    <td>
                                         <div className="role-participant-box">
                                            <div className="role-label">Conductor:</div>
                                            <CustomSelect options={lists['discursantes'] || []} value={getValue(`${pathPrefix}.conductor`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.conductor`, val)} historyProvider={history} />
                                        </div>
                                        {part.hasOwnProperty('lector') && (
                                            <div className="role-participant-box" style={{marginTop: '8px'}}>
                                                <div className="role-label">Lector:</div>
                                                <CustomSelect options={lists['lectores_libro'] || []} value={getValue(`${pathPrefix}.lector`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.lector`, val)} historyProvider={history} />
                                            </div>
                                        )}
                                    </td>
                                </tr>
                            );
                        }
                        return <tr key={pathPrefix}><td>{part.titulo}</td><td colSpan={3}></td></tr>;
                    })}
                     <tr><td><strong>Oración Final:</strong></td><td></td><td></td><td><CustomSelect options={lists['oradores'] || []} value={getValue('oracion.final') || ''} onChange={val => handleDataChange(selectedWeek, 'oracion.final', val)} historyProvider={history} /></td></tr>
                </tbody>
            </table>
        </div>
    )
}


const Programa: React.FC = () => {
    const { programs, lists, history, loading, error, refetch } = useProgramData();
    const [selectedWeek, setSelectedWeek] = useState('');
    const [programData, setProgramData] = useState<any | null>(null);
    const [saveStatus, setSaveStatus] = useState<{ message: string, type: 'error' | 'success' | 'loading' } | null>(null);
    const [printStartWeek, setPrintStartWeek] = useState('');
    const [printEndWeek, setPrintEndWeek] = useState('');

    useEffect(() => {
        if (programs.length > 0 && !selectedWeek) {
            const today = new Date();
            const closest = programs.reduce((prev: any, curr: any) => 
                (Math.abs(new Date(curr.week_id).getTime() - today.getTime()) < Math.abs(new Date(prev.week_id).getTime() - today.getTime()) ? curr : prev)
            );
            const initialWeek = closest?.week_id || programs[0]?.week_id || '';
            setSelectedWeek(initialWeek);
            setPrintStartWeek(initialWeek);
            setPrintEndWeek(initialWeek);
        }
    }, [programs, selectedWeek]);

    useEffect(() => {
        if (selectedWeek && programs.length > 0) {
            const data = programs.find(p => p.week_id === selectedWeek)?.data;
            if (data) {
                setProgramData(JSON.parse(JSON.stringify(data)));
            }
        }
    }, [selectedWeek, programs]);

    const handleDataChange = (weekId: string, path: string, value: any) => {
        if (!programData || weekId !== selectedWeek) return;
        setProgramData((prev: any) => {
            const newData = JSON.parse(JSON.stringify(prev));
            const keys = path.split('.');
            let current = newData;
            for (let i = 0; i < keys.length - 1; i++) {
                const key = keys[i];
                if (!current[key]) current[key] = !isNaN(parseInt(keys[i+1], 10)) ? [] : {};
                current = current[key];
            }
            current[keys[keys.length - 1]] = value;
            return newData;
        });
    };

    const handleSave = async () => {
        if (!programData || !selectedWeek) return;
        setSaveStatus({ message: 'Guardando...', type: 'loading' });

        const { error: updateError } = await supabase.from('programas').update({ data: programData }).eq('week_id', selectedWeek);

        if (updateError) { 
            setSaveStatus({ message: `Error: ${updateError.message}`, type: 'error' }); 
        } else {
            setSaveStatus({ message: '¡Guardado con éxito!', type: 'success' });
            refetch();
        }
        setTimeout(() => setSaveStatus(null), 3000);
    };

    const handleOpenPrintPreview = () => {
        if (!printStartWeek || !printEndWeek) {
            alert('Por favor seleccione un rango de fechas válido');
            return;
        }

        const weeks = programs
            .map(p => p.week_id)
            .sort()
            .filter(w => w >= printStartWeek && w <= printEndWeek);

        if (weeks.length === 0) {
            alert('No hay programas en el rango seleccionado');
            return;
        }

        const programsToPrint = weeks.map(week => ({
            data: week === selectedWeek ? programData : programs.find(p => p.week_id === week)?.data,
            week_id: week
        }));

        const html = buildPrintableHTML(programsToPrint);
        const printWindow = window.open('', '_blank');
        if (printWindow) {
            printWindow.document.open();
            printWindow.document.write(html);
            printWindow.document.close();
        } else {
            alert("Por favor, permita las ventanas emergentes para esta página.");
        }
    };

    const handleDownloadPdf = async () => {
        if (typeof html2pdf === 'undefined') {
            alert('La función de PDF no está lista. Espere un momento.');
            return;
        }

        if (!printStartWeek || !printEndWeek) {
            alert('Por favor seleccione un rango de fechas válido');
            return;
        }

        const weeks = programs
            .map(p => p.week_id)
            .sort()
            .filter(w => w >= printStartWeek && w <= printEndWeek);

        if (weeks.length === 0) {
            alert('No hay programas en el rango seleccionado');
            return;
        }

        setSaveStatus({ message: 'Generando PDF...', type: 'loading' });

        const programsToPrint = weeks.map(week => ({
            data: week === selectedWeek ? programData : programs.find(p => p.week_id === week)?.data,
            week_id: week
        }));

        const htmlContent = buildPrintableHTML(programsToPrint);

        const container = document.createElement('div');
        container.style.position = 'absolute';
        container.style.left = '-9999px';
        container.innerHTML = htmlContent;

        // Remover acciones de impresión del contenedor temporal
        const actions = container.querySelector('.print-actions');
        if (actions) actions.remove();

        document.body.appendChild(container);

        const opt = {
            margin: 0,
            filename: `programas_${printStartWeek}_${printEndWeek}.pdf`,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { scale: 2, useCORS: true, logging: false },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        try {
            await html2pdf().from(container).set(opt).save();
            setSaveStatus({ message: 'PDF descargado con éxito', type: 'success' });
        } catch (err) {
            console.error("PDF generation failed:", err);
            setSaveStatus({ message: 'Error al generar el PDF', type: 'error' });
        } finally {
            document.body.removeChild(container);
            setTimeout(() => setSaveStatus(null), 3000);
        }
    };

    const getValue = (path: string) => path.split('.').reduce((o, key) => o?.[key], programData);
    if (loading) return <div>Cargando programa...</div>;
    if (error) return <div className="text-red-600">Error al cargar: {error}</div>;

    return (
        <div className="container mx-auto px-4 py-8 programa-page">
            <div className="programa-controls-box">
                <label htmlFor="week-selector">Seleccione Semana:</label>
                <select id="week-selector" value={selectedWeek} onChange={e => setSelectedWeek(e.target.value)}>
                    {programs.map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
                </select>
            </div>
            {saveStatus && <div className={`text-center font-semibold p-4 mb-4 rounded-lg bg-${saveStatus.type === 'error' ? 'red-100 text-red-800' : saveStatus.type === 'success' ? 'green-100 text-green-800' : 'blue-100 text-blue-800'}`}>{saveStatus.message}</div>}

            <DesktopProgramView programData={programData} getValue={getValue} handleDataChange={handleDataChange} lists={lists} history={history} selectedWeek={selectedWeek} />
            <MobileProgramView programData={programData} getValue={getValue} handleDataChange={handleDataChange} lists={lists} history={history} selectedWeek={selectedWeek} />

             <div className="program-controls-footer">
                <div className="print-controls-group">
                    <div className="print-control-item">
                        <label htmlFor="print-start-week">Imprimir desde:</label>
                        <select 
                            id="print-start-week" 
                            value={printStartWeek} 
                            onChange={e => {
                                const newStart = e.target.value;
                                setPrintStartWeek(newStart);
                                if (printEndWeek < newStart) {
                                    setPrintEndWeek(newStart);
                                }
                            }}
                        >
                            {programs.map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
                        </select>
                    </div>
                    <div className="print-control-item">
                        <label htmlFor="print-end-week">hasta:</label>
                        <select 
                            id="print-end-week" 
                            value={printEndWeek} 
                            onChange={e => setPrintEndWeek(e.target.value)}
                        >
                            {programs.filter(p => p.week_id >= printStartWeek).map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
                        </select>
                    </div>
                    <div className="print-control-item">
                        <label htmlFor="watermark-text">Marca de agua:</label>
                        <input 
                            type="text" 
                            id="watermark-text" 
                            value={programData?.watermark ?? 'PRELIMINAR'} 
                            onChange={e => handleDataChange(selectedWeek, 'watermark', e.target.value)} 
                        />
                    </div>
                    <div className="print-control-item">
                        <label htmlFor="toggle-blur">
                            <input 
                                type="checkbox" 
                                id="toggle-blur" 
                                checked={programData?.isBlurred ?? false} 
                                onChange={e => handleDataChange(selectedWeek, 'isBlurred', e.target.checked)} 
                            />
                            Difuminar
                        </label>
                    </div>
                </div>
                 <div className="footer-actions">
                    <button onClick={handleOpenPrintPreview} className="button-print">
                        <i className="fas fa-print"></i> Vista Previa (2/hoja)
                    </button>
                    <button onClick={handleDownloadPdf} className="download-button">
                        <i className="fas fa-file-pdf"></i> Descargar PDF
                    </button>
                    <button onClick={handleSave} className="button-save">
                        <i className="fas fa-save"></i> Guardar Cambios
                    </button>
                </div>
            </div>
        </div>
    );
};

