            .print-actions button.primary:hover { background: #1d4ed8; }
            .print-actions button.pdf-btn { background: #059669; color: #fff; border-color: #047857; }
            .print-actions button.pdf-btn:hover { background: #047857; }

            #print-container { width: 210mm; margin: 20px auto; background-color: transparent; }

            .print-page {
                width: 210mm;
                height: 297mm;
                padding: 10mm;
                box-sizing: border-box;
                display: flex;
                flex-direction: column;
                page-break-after: always;
                position: relative;
                background: #ffffff;
                box-shadow: 0 10px 25px rgba(0,0,0,0.05);
                margin-bottom: 20px;
                border-radius: 4px;
            }
            .print-page:last-child { page-break-after: auto; }

            .printable-program { 
                height: 135mm; 
                overflow: hidden;
                display: flex;
                flex-direction: column;
                position: relative;
                box-sizing: border-box;
