declare const html2pdf: any;

const buildPrintableHTML = (programs: any[]) => {
    const safe = (v: any) => (v == null ? '' : String(v));
    const formatPair = (str: string | null | undefined): string => {
        if (!str) return '';
        const parts = str.split('/').map(s => s.trim()).filter(Boolean);
        if (parts.length > 1) {
            return `${parts[0]} /<br>${parts[1]}`;
        }
        return parts[0] || '';
    };

    const pages: any[][] = [];
    for (let i = 0; i < programs.length; i += 2) {
        pages.push(programs.slice(i, i + 2));
    }

    const pagesHTML = pages.map(pagePrograms => {
        const pageContentHTML = pagePrograms.map((program, idx) => {
            const data = program.data || {};
            const title = safe(data.titulo) || `Programa ${program.week_id || ''}`;
            const canciones = data.canciones || {};
            const rooms = ["Sala Auxiliar N°3", "Sala Auxiliar N°2", "Auditorio principal"];
            const watermarkText = data.watermark ?? 'PRELIMINAR';
            const isBlurred = data.isBlurred ?? false;

            return `
                <div class="printable-program ${isBlurred ? 'blurred' : ''}" data-watermark="${watermarkText}">
                    <table class="print-table">
                        <colgroup>
                            <col class="col-parte">
                            <col class="col-sala">
                            <col class="col-sala">
                            <col class="col-sala">
                        </colgroup>
                        <thead>
                            <tr><th colspan="4" class="print-title">${title}</th></tr>
                            <tr>
                                <th></th>
                                <th>${rooms[0]}</th>
                                <th>${rooms[1]}</th>
                                <th>${rooms[2]}</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr><td><strong>Presidente:</strong></td><td class="participante">${safe(data.presidentes?.aux3)}</td><td class="participante">${safe(data.presidentes?.aux2)}</td><td class="participante">${safe(data.presidentes?.principal)}</td></tr>
                            <tr><td><strong>Oración de Inicio:</strong></td><td></td><td></td><td class="participante">${safe(data.oracion?.inicio)}</td></tr>
                            <tr><td>• <b>${safe(canciones.inicio)}</b></td><td></td><td></td><td></td></tr>
                            <tr><td>• Palabras de introducción (1 min.)</td><td></td><td></td><td></td></tr>
                            <tr class="section tesoros"><td colspan="4">TESOROS DE LA BIBLIA</td></tr>
                            <tr><td>${safe(data.tesoros?.p1?.title)}</td><td></td><td></td><td class="participante">${safe(data.tesoros?.p1?.main)}</td></tr>
                            <tr><td>${safe(data.tesoros?.p2?.title)}</td><td></td><td></td><td class="participante">${safe(data.tesoros?.p2?.main)}</td></tr>
                            <tr><td>${safe(data.tesoros?.p3?.title) || '3. Lectura de la Biblia (3 min.)'}</td><td class="participante">${safe(data.tesoros?.p3?.aux3)}</td><td class="participante">${safe(data.tesoros?.p3?.aux2)}</td><td class="participante">${safe(data.tesoros?.p3?.main)}</td></tr>
                            <tr class="section maestros"><td colspan="4">SEAMOS MEJORES MAESTROS</td></tr>
                            ${(data.maestros || []).map((m: any) => `
                                <tr>
                                    <td>${safe(m.title)}</td>
                                    <td class="participante">${formatPair(m.aux3)}</td>
                                    <td class="participante">${formatPair(m.aux2)}</td>
                                    <td class="participante">${formatPair(m.main)}</td>
                                </tr>
                            `).join('')}
                            <tr class="section vida-cristiana"><td colspan="4">NUESTRA VIDA CRISTIANA</td></tr>
                            <tr><td>• <b>${safe(canciones.vidaCristiana)}</b></td><td></td><td></td><td></td></tr>
                            ${(data.vidaCristiana || []).map((v: any) => {
                                let participantDetail = '';
                                if (v.hasOwnProperty('conductor')) {
                                    participantDetail = safe(v.conductor);
                                    if (v.lector) {
                                        participantDetail += `<br>Lector: ${safe(v.lector)}`;
                                    }
                                } else if (v.hasOwnProperty('discursante')) {
                                    participantDetail = safe(v.discursante);
                                }
                                return `
                                    <tr>
                                        <td>• ${safe(v.titulo)}</td>
                                        <td></td>
                                        <td></td>
                                        <td class="participante">${participantDetail}</td>
                                    </tr>
                                `;
                            }).join('')}
                            <tr><td>• Palabras de conclusión (3 mins.)</td><td></td><td></td><td></td></tr>
                            <tr><td>• <b>${safe(canciones.final)}</b></td><td></td><td></td><td></td></tr>
                            <tr><td><strong>Oración Final:</strong></td><td></td><td></td><td class="participante">${safe(data.oracion?.final)}</td></tr>
                        </tbody>
                    </table>
                </div>
                ${idx === 0 && pagePrograms.length > 1 ? '<div class="page-divider"></div>' : ''}
            `;
        }).join('');

        return `<div class="print-page">${pageContentHTML}</div>`;
    }).join('');

    const styles = `
        <style>
            @media print { 
                @page { size: A4 portrait; margin: 0; } 
                html, body { margin: 0; padding: 0; background: #fff !important; }
                body { font-size: 10pt; -webkit-print-color-adjust: exact !important; color-adjust: exact !important; } 
                .no-print { display: none !important; }
                .print-page { margin: 0; border: none; box-shadow: none; page-break-after: always; height: 296mm; }
            }
            body { font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif; margin: 0; padding: 0; color: #1e293b; background-color: #f1f5f9; }

            .print-actions { position: sticky; top: 0; background-color: rgba(255, 255, 255, 0.95); backdrop-filter: blur(10px); z-index: 1000; padding: 12px; border-bottom: 1px solid #e2e8f0; display:flex; gap:12px; align-items:center; justify-content:center; }
            .print-actions button { font-size: 0.95em; padding: 10px 24px; border: 1px solid #cbd5e1; border-radius: 8px; cursor: pointer; background:#fff; font-weight: 600; color: #334155; transition: all 0.2s; display: flex; align-items: center; gap: 8px; }
            .print-actions button:hover { background: #f8fafc; border-color: #94a3b8; }
            .print-actions button.primary { background: #2563eb; color: #fff; border-color: #1d4ed8; }
            .print-actions button.pdf-btn { background: #10b981; color: #fff; border-color: #059669; }

            #print-container { width: 210mm; margin: 0 auto; background-color: transparent; padding-top: 10px; }

            .print-page {
                width: 210mm;
                height: 297mm;
                padding: 8mm 10mm;
                box-sizing: border-box;
                display: flex;
                flex-direction: column;
                position: relative;
                background: #ffffff;
                box-shadow: 0 4px 20px rgba(0,0,0,0.1);
                margin-bottom: 15px;
            }

            .printable-program { 
                flex: 1;
                overflow: hidden;
                display: flex;
                flex-direction: column;
                position: relative;
                box-sizing: border-box;
                background: #fff;
                max-height: 138mm;
            }

            .page-divider {
                height: 0;
                border-top: 2px dashed #e2e8f0;
                margin: 4mm 0;
                width: 100%;
            }

            .print-table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 10pt; border: 1.5px solid #000; }
            .print-title { font-size: 16pt; font-weight: 800; padding: 8px; border-bottom: 1.5px solid #000; color: #000; text-align: center; text-transform: uppercase; }
            .print-table th, .print-table td { padding: 4px 6px; vertical-align: middle; line-height: 1.2; border: 1px solid #000; text-align: left; }
            .print-table th { text-align: center; font-weight: 700; font-size: 9.5pt; background-color: #f8fafc; }
            .print-table td.participante { text-align: center; font-weight: 500; color: #000; }
            .col-parte { width: 35%; }
            .col-sala { width: 21.6%; }

            .section td { font-weight: 900; text-transform: uppercase; color: #fff; padding: 6px 8px; text-align: center !important; font-size: 10.5pt; border: 1px solid #000 !important; }
            .section.tesoros td { background-color: #475569 !important; }
            .section.maestros td { background-color: #b45309 !important; }
            .section.vida-cristiana td { background-color: #9f1239 !important; }

            .printable-program.blurred { position: relative; }
            .printable-program.blurred::before { 
                content: attr(data-watermark); 
                position: absolute; 
                top: 50%; 
                left: 50%; 
                transform: translate(-50%, -50%) rotate(-35deg); 
                font-size: 5em; 
                color: rgba(0,0,0,0.1); 
                font-weight: 900; 
                pointer-events: none; 
                z-index: 1000; 
                white-space: nowrap;
            }
            .printable-program.blurred .print-table { filter: blur(5px); opacity: 0.6; }
        </style>
    `;

    return `
        <!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Programa VMT - Vista Previa</title>
        <script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script>
        <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
        ${styles}</head><body>
            <div class="print-actions no-print">
                <button class="primary" onclick="window.print()"><i class="fas fa-print"></i> Imprimir Ahora</button>
                <button class="pdf-btn" onclick="generatePDF()"><i class="fas fa-file-pdf"></i> Descargar PDF</button>
                <button onclick="window.close()"><i class="fas fa-times"></i> Cerrar Vista</button>
            </div>
            <div id="print-container">${pagesHTML}</div>
