            </div>
        </div>
    );

    const renderTesorosTab = () => (
         <div className="mobile-card">
            <div className="mobile-card__header tesoros-header">Tesoros de la Biblia</div>
            <div className="mobile-card__body">
                <MobileAssignmentRow label={getValue('tesoros.p1.title') || 'Discurso'}><CustomSelect options={lists['discursantes'] || []} value={getValue('tesoros.p1.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p1.main', val)} historyProvider={history} /></MobileAssignmentRow>
