const Programa: React.FC = () => {
    const { programs, lists, history, loading, error, refetch } = useProgramData();
    const [selectedWeek, setSelectedWeek] = useState('');
    const [programData, setProgramData] = useState<any | null>(null);
    const [saveStatus, setSaveStatus] = useState<{ message: string, type: 'error' | 'success' | 'loading' } | null>(null);
    const [printStartWeek, setPrintStartWeek] = useState('');
    const [printEndWeek, setPrintEndWeek] = useState('');

    useEffect(() => {
        if (programs.length > 0 && !selectedWeek) {
            const today = new Date();
            const closest = programs.reduce((prev: any, curr: any) => 
                (Math.abs(new Date(curr.week_id).getTime() - today.getTime()) < Math.abs(new Date(prev.week_id).getTime() - today.getTime()) ? curr : prev)
            );
            const initialWeek = closest?.week_id || programs[0]?.week_id || '';
            setSelectedWeek(initialWeek);
            setPrintStartWeek(initialWeek);
            setPrintEndWeek(initialWeek);
        }
    }, [programs, selectedWeek]);

    useEffect(() => {
        if (selectedWeek && programs.length > 0) {
            const found = programs.find(p => p.week_id === selectedWeek);
            if (found?.data) {
                setProgramData(JSON.parse(JSON.stringify(found.data)));
            }
        }
    }, [selectedWeek, programs]);

    const handleDataChange = (weekId: string, path: string, value: any) => {
        if (!programData || weekId !== selectedWeek) return;
        setProgramData((prev: any) => {
            const newData = JSON.parse(JSON.stringify(prev));
            const keys = path.split('.');
            let current = newData;
            for (let i = 0; i < keys.length - 1; i++) {
                const key = keys[i];
                if (!current[key]) current[key] = !isNaN(parseInt(keys[i+1], 10)) ? [] : {};
                current = current[key];
            }
            current[keys[keys.length - 1]] = value;
            return newData;
        });
    };

    const handleSave = async () => {
        if (!programData || !selectedWeek) return;
        setSaveStatus({ message: 'Guardando...', type: 'loading' });

        const { error: updateError } = await supabase.from('programas').update({ data: programData }).eq('week_id', selectedWeek);

        if (updateError) { 
            setSaveStatus({ message: `Error: ${updateError.message}`, type: 'error' }); 
        } else {
            setSaveStatus({ message: '¡Guardado con éxito!', type: 'success' });
            refetch();
        }
        setTimeout(() => setSaveStatus(null), 3000);
    };

    const handleOpenPrintPreview = () => {
        if (!printStartWeek || !printEndWeek) {
            alert('Por favor seleccione un rango de fechas válido');
            return;
        }

        const weeks = programs
            .map(p => p.week_id)
            .sort()
            .filter(w => w >= printStartWeek && w <= printEndWeek);

        if (weeks.length === 0) {
            alert('No hay programas en el rango seleccionado');
            return;
        }

        const programsToPrint = weeks.map(week => ({
            data: week === selectedWeek ? programData : programs.find(p => p.week_id === week)?.data,
            week_id: week
        }));

        const html = buildPrintableHTML(programsToPrint);
        const printWindow = window.open('', '_blank');
        if (printWindow) {
            printWindow.document.open();
            printWindow.document.write(html);
            printWindow.document.close();
        } else {
            alert("Por favor, permita las ventanas emergentes para esta página.");
        }
    };

    const getValue = (path: string) => path.split('.').reduce((o, key) => o?.[key], programData);

    if (loading) return <div className="p-10 text-center">Cargando programa...</div>;
    if (error) return <div className="p-10 text-center text-red-600">Error al cargar: {error}</div>;

    const currentTitle = programData?.titulo || selectedWeek;

    return (
        <div className="container mx-auto px-4 py-8 programa-page">
            <h1 className="page-title">Editor de Programa</h1>

            <div className="programa-controls-box">
                <label htmlFor="week-selector">Seleccione Semana para editar:</label>
                <select id="week-selector" value={selectedWeek} onChange={e => setSelectedWeek(e.target.value)}>
                    {programs.map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
                </select>
            </div>

            {saveStatus && (
                <div className={`text-center font-semibold p-4 mb-4 rounded-lg bg-${saveStatus.type === 'error' ? 'red-100 text-red-800' : saveStatus.type === 'success' ? 'green-100 text-green-800' : 'blue-100 text-blue-800'}`}>
                    {saveStatus.message}
                </div>
            )}

            {programData && (
                <div className="programa-desktop-view">
                    <div className="bg-white rounded-xl shadow-lg p-6 border border-gray-100">
                        <h2 className="text-xl font-bold mb-4 text-blue-800 border-b pb-2">{currentTitle}</h2>
                        <table className="main-program-table w-full border-collapse">
                            <tbody>
                                <tr>
                                    <td className="p-2 border"><strong>Presidente:</strong></td>
                                    <td className="p-2 border">
                                        <div className="text-xs text-gray-500 mb-1">Sala 3</div>
                                        <CustomSelect options={lists['consejeros'] || []} value={getValue('presidentes.aux3') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.aux3', val)} historyProvider={history} />
                                    </td>
                                    <td className="p-2 border">
                                        <div className="text-xs text-gray-500 mb-1">Sala 2</div>
                                        <CustomSelect options={lists['consejeros'] || []} value={getValue('presidentes.aux2') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.aux2', val)} historyProvider={history} />
                                    </td>
                                    <td className="p-2 border">
                                        <div className="text-xs text-gray-500 mb-1">Principal</div>
                                        <CustomSelect options={lists['presidentes'] || []} value={getValue('presidentes.principal') || ''} onChange={val => handleDataChange(selectedWeek, 'presidentes.principal', val)} historyProvider={history} />
                                    </td>
                                </tr>
                                <tr>
                                    <td className="p-2 border"><strong>Oración de Inicio:</strong></td>
                                    <td className="p-2 border" colSpan={2}></td>
                                    <td className="p-2 border"><CustomSelect options={lists['oradores'] || []} value={getValue('oracion.inicio') || ''} onChange={val => handleDataChange(selectedWeek, 'oracion.inicio', val)} historyProvider={history} /></td>
                                </tr>

                                <tr className="section tesoros"><td colSpan={4} className="section-header py-2 text-center font-bold text-white bg-slate-600">Tesoros de la Biblia</td></tr>
                                <tr><td className="p-2 border">{getValue('tesoros.p1.title') || '1. Punto 1'}</td><td className="p-2 border" colSpan={2}></td><td className="p-2 border"><CustomSelect options={lists['discursantes'] || []} value={getValue('tesoros.p1.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p1.main', val)} historyProvider={history} /></td></tr>
                                <tr><td className="p-2 border">{getValue('tesoros.p2.title') || '2. Perlas'}</td><td className="p-2 border" colSpan={2}></td><td className="p-2 border"><CustomSelect options={lists['discursantes'] || []} value={getValue('tesoros.p2.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p2.main', val)} historyProvider={history} /></td></tr>
                                <tr>
                                    <td className="p-2 border">{getValue('tesoros.p3.title') || '3. Lectura Biblia'}</td>
                                    <td className="p-2 border"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.aux3') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.aux3', val)} historyProvider={history} /></td>
                                    <td className="p-2 border"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.aux2') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.aux2', val)} historyProvider={history} /></td>
                                    <td className="p-2 border"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.main', val)} historyProvider={history} /></td>
                                </tr>

                                <tr className="section maestros"><td colSpan={4} className="section-header py-2 text-center font-bold text-white bg-amber-600">Seamos Mejores Maestros</td></tr>
                                {(getValue('maestros') || []).map((part: any, i: number) => (
                                    <tr key={`mae-${i}`}>
                                        <td className="p-2 border">{part.title}</td>
                                        {['aux3', 'aux2', 'main'].map(room => (
                                            <td key={room} className="p-2 border">
                                                <div className="text-xs text-gray-400 mb-1">{room === 'main' ? 'Principal' : room === 'aux2' ? 'Sala 2' : 'Sala 3'}</div>
                                                <CustomSelect 
                                                    options={lists[part.title?.toLowerCase().includes('discurso') ? 'maestros_discurso' : 'publicadores'] || []} 
                                                    value={getValue(`maestros.${i}.${room}`) || ''} 
                                                    onChange={val => handleDataChange(selectedWeek, `maestros.${i}.${room}`, val)} 
                                                    historyProvider={history} 
                                                />
                                            </td>
                                        ))}
                                    </tr>
                                ))}

                                <tr className="section vida-cristiana"><td colSpan={4} className="section-header py-2 text-center font-bold text-white bg-rose-700">Nuestra Vida Cristiana</td></tr>
                                {(getValue('vidaCristiana') || []).map((part: any, i: number) => {
                                    const pathPrefix = `vidaCristiana.${i}`;
                                    return (
                                        <tr key={pathPrefix}>
                                            <td className="p-2 border">{part.titulo}</td>
                                            <td className="p-2 border" colSpan={2}></td>
                                            <td className="p-2 border">
                                                {part.hasOwnProperty('conductor') ? (
                                                    <div className="flex flex-col gap-2">
                                                        <div><span className="text-xs font-bold mr-1">Cond:</span><CustomSelect options={lists['discursantes'] || []} value={getValue(`${pathPrefix}.conductor`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.conductor`, val)} historyProvider={history} /></div>
                                                        {part.hasOwnProperty('lector') && (<div><span className="text-xs font-bold mr-1">Lect:</span><CustomSelect options={lists['lectores_libro'] || []} value={getValue(`${pathPrefix}.lector`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.lector`, val)} historyProvider={history} /></div>)}
                                                    </div>
                                                ) : part.hasOwnProperty('discursante') ? (
                                                    <CustomSelect options={lists['discursantes'] || []} value={getValue(`${pathPrefix}.discursante`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.discursante`, val)} historyProvider={history} />
                                                ) : null}
                                            </td>
                                        </tr>
                                    );
                                })}
                                <tr>
                                    <td className="p-2 border"><strong>Oración Final:</strong></td>
                                    <td className="p-2 border" colSpan={2}></td>
                                    <td className="p-2 border"><CustomSelect options={lists['oradores'] || []} value={getValue('oracion.final') || ''} onChange={val => handleDataChange(selectedWeek, 'oracion.final', val)} historyProvider={history} /></td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            <div className="program-controls-footer">
                <div className="print-controls-group">
                    <div className="print-control-item">
                        <label>Imprimir desde:</label>
                        <select value={printStartWeek} onChange={e => { setPrintStartWeek(e.target.value); if(printEndWeek < e.target.value) setPrintEndWeek(e.target.value); }}>
                            {programs.map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
