                    </div>
                    <div className="print-control-item">
                        <label>hasta:</label>
                        <select value={printEndWeek} onChange={e => setPrintEndWeek(e.target.value)}>
                            {programs.filter(p => p.week_id >= printStartWeek).map(p => <option key={p.week_id} value={p.week_id}>{p.data?.titulo || p.week_id}</option>)}
