declare const html2pdf: any;

const buildPrintableHTML = (programs: any[]) => {
    const safe = (v: any) => (v == null ? '' : String(v));
    const formatPair = (str: string | null | undefined): string => {
        if (!str) return '';
        const parts = str.split('/').map(s => s.trim()).filter(Boolean);
        if (parts.length > 1) {
            return `${parts[0]} /<br>${parts[1]}`;
        }
        return parts[0] || '';
    };

    const pages: any[][] = [];
    for (let i = 0; i < programs.length; i += 2) {
        pages.push(programs.slice(i, i + 2));
    }

    const pagesHTML = pages.map(pagePrograms => {
        const pageContentHTML = pagePrograms.map((program, idx) => {
            const data = program.data || {};
            const title = safe(data.titulo) || `Programa ${program.week_id || ''}`;
            const canciones = data.canciones || {};
            const watermarkText = data.watermark ?? 'PRELIMINAR';
            const isBlurred = data.isBlurred ?? false;

            return `
                <div class="printable-program ${isBlurred ? 'blurred' : ''}" data-watermark="${watermarkText}">
                    <table class="print-table">
                        <colgroup>
                            <col class="col-parte">
                            <col class="col-sala">
                            <col class="col-sala">
                            <col class="col-sala">
                        </colgroup>
                        <thead>
                            <tr><th colspan="4" class="print-header-date">${title}</th></tr>
                            <tr class="room-headers">
                                <th></th>
                                <th>Sala Auxiliar N°3</th>
                                <th>Sala Auxiliar N°2</th>
                                <th>Auditorio principal</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <td class="part-label"><strong>Presidente:</strong></td>
                                <td class="participante">${safe(data.presidentes?.aux3)}</td>
                                <td class="participante">${safe(data.presidentes?.aux2)}</td>
                                <td class="participante">${safe(data.presidentes?.principal)}</td>
                            </tr>
                            <tr>
                                <td class="part-label"><strong>Oración de Inicio:</strong></td>
                                <td></td>
                                <td></td>
                                <td class="participante">${safe(data.oracion?.inicio)}</td>
                            </tr>
                            <tr class="item-row">
                                <td colspan="4" class="part-label">• <b>${safe(canciones.inicio)}</b></td>
                            </tr>
                            <tr class="item-row">
                                <td colspan="4" class="part-label">• Palabras de introducción (1 min.)</td>
                            </tr>

                            <tr class="section tesoros"><td colspan="4">TESOROS DE LA BIBLIA</td></tr>
                            <tr>
                                <td class="part-label">${safe(data.tesoros?.p1?.title)}</td>
                                <td></td>
                                <td></td>
                                <td class="participante">${safe(data.tesoros?.p1?.main)}</td>
                            </tr>
                            <tr>
                                <td class="part-label">${safe(data.tesoros?.p2?.title)}</td>
                                <td></td>
                                <td></td>
                                <td class="participante">${safe(data.tesoros?.p2?.main)}</td>
                            </tr>
                            <tr>
                                <td class="part-label">${safe(data.tesoros?.p3?.title) || '3. Lectura de la Biblia (3 min.)'}</td>
                                <td class="participante">${safe(data.tesoros?.p3?.aux3)}</td>
                                <td class="participante">${safe(data.tesoros?.p3?.aux2)}</td>
                                <td class="participante">${safe(data.tesoros?.p3?.main)}</td>
                            </tr>

                            <tr class="section maestros"><td colspan="4">SEAMOS MEJORES MAESTROS</td></tr>
                            ${(data.maestros || []).map((m: any) => `
                                <tr>
                                    <td class="part-label">${safe(m.title)}</td>
                                    <td class="participante">${formatPair(m.aux3)}</td>
                                    <td class="participante">${formatPair(m.aux2)}</td>
                                    <td class="participante">${formatPair(m.main)}</td>
                                </tr>
                            `).join('')}

                            <tr class="section vida-cristiana"><td colspan="4">NUESTRA VIDA CRISTIANA</td></tr>
                            <tr class="item-row">
                                <td colspan="4" class="part-label">• <b>${safe(canciones.vidaCristiana)}</b></td>
                            </tr>
                            ${(data.vidaCristiana || []).map((v: any) => {
                                let participantDetail = '';
                                if (v.hasOwnProperty('conductor')) {
                                    participantDetail = safe(v.conductor);
                                    if (v.lector) {
                                        participantDetail = `${safe(v.conductor)}<br>Lector: ${safe(v.lector)}`;
                                    }
                                } else if (v.hasOwnProperty('discursante')) {
                                    participantDetail = safe(v.discursante);
                                }
                                return `
                                    <tr>
                                        <td class="part-label">• ${safe(v.titulo)}</td>
                                        <td></td>
                                        <td></td>
                                        <td class="participante">${participantDetail}</td>
                                    </tr>
                                `;
                            }).join('')}
                            <tr class="item-row">
                                <td colspan="4" class="part-label">• Palabras de conclusión (3 mins.)</td>
                            </tr>
                            <tr class="item-row">
                                <td colspan="4" class="part-label">• <b>${safe(canciones.final)}</b></td>
                            </tr>
                            <tr>
                                <td class="part-label"><strong>Oración Final:</strong></td>
                                <td></td>
                                <td></td>
                                <td class="participante">${safe(data.oracion?.final)}</td>
                            </tr>
                        </tbody>
                    </table>
                </div>
                ${idx === 0 && pagePrograms.length > 1 ? '<div class="page-divider"></div>' : ''}
            `;
        }).join('');

        return `<div class="print-page">${pageContentHTML}</div>`;
    }).join('');

    const styles = `
        <style>
            @media print { 
                @page { size: A4 portrait; margin: 0; } 
                html, body { margin: 0; padding: 0; background: #fff !important; }
                body { font-size: 8.5pt; -webkit-print-color-adjust: exact !important; color-adjust: exact !important; } 
                .no-print { display: none !important; }
                .print-page { 
                    margin: 0; 
                    border: none; 
                    box-shadow: none; 
                    page-break-after: always; 
                    height: 297mm; 
                    width: 210mm;
                    overflow: hidden;
                }
            }
            body { font-family: "Segoe UI", "Arial", sans-serif; margin: 0; padding: 0; color: #000; background-color: #f1f5f9; }

            .print-actions { position: sticky; top: 0; background-color: rgba(255, 255, 255, 0.95); backdrop-filter: blur(10px); z-index: 1000; padding: 12px; border-bottom: 1px solid #e2e8f0; display:flex; gap:12px; align-items:center; justify-content:center; }
            .print-actions button { font-size: 0.95em; padding: 10px 24px; border: 1px solid #cbd5e1; border-radius: 8px; cursor: pointer; background:#fff; font-weight: 600; color: #334155; transition: all 0.2s; display: flex; align-items: center; gap: 8px; }
            .print-actions button:hover { background: #f8fafc; border-color: #94a3b8; }
            .print-actions button.primary { background: #2563eb; color: #fff; border-color: #1d4ed8; }
            .print-actions button.pdf-btn { background: #10b981; color: #fff; border-color: #059669; }

            #print-container { width: 210mm; margin: 0 auto; background-color: transparent; padding: 0; }

            .print-page {
                width: 210mm;
                height: 297mm;
                padding: 6mm 10mm;
                box-sizing: border-box;
                display: flex;
                flex-direction: column;
                position: relative;
                background: #ffffff;
                box-shadow: 0 4px 20px rgba(0,0,0,0.1);
                margin-bottom: 15px;
                page-break-after: always;
            }

            .printable-program { 
                height: 138mm; 
                max-height: 138mm;
                overflow: hidden;
                display: flex;
                flex-direction: column;
                position: relative;
                box-sizing: border-box;
                background: #fff;
            }

            .page-divider {
                height: 0;
                border-top: 1px dashed #cbd5e1;
                margin: 4mm 0;
                width: 100%;
            }

            .print-table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 8.5pt; border: 1px solid #ccc; }
            .print-header-date { font-size: 11.5pt; font-weight: 700; padding: 4px; border: 1px solid #ccc; text-align: center; text-transform: uppercase; background: #fff; color: #000; }

            .room-headers th { padding: 2px 2px; border: 1px solid #ccc; text-align: center; font-weight: 600; font-size: 9pt; background: #f8fafc; }

            .print-table td { padding: 2px 4px; vertical-align: middle; line-height: 1.05; border: 1px solid #ccc; }
            .print-table td.participante { text-align: center; font-weight: 400; color: #000; }
            .part-label { text-align: left; }

            .col-parte { width: 38%; }
            .col-sala { width: 20.6%; }

            .section td { font-weight: 800; text-transform: uppercase; color: #fff; padding: 4px 10px; text-align: center !important; font-size: 9.5pt; border: 1px solid #000 !important; }
            .section.tesoros td { background-color: #475569 !important; } 
            .section.maestros td { background-color: #c19a26 !important; } 
            .section.vida-cristiana td { background-color: #8b2c39 !important; } 

            .printable-program.blurred { position: relative; }
            .printable-program.blurred::before { 
                content: attr(data-watermark); 
                position: absolute; 
                top: 50%; 
                left: 50%; 
                transform: translate(-50%, -50%) rotate(-35deg); 
                font-size: 4em; 
                color: rgba(0,0,0,0.08); 
                font-weight: 900; 
                pointer-events: none; 
                z-index: 1000; 
                white-space: nowrap;
            }
            .printable-program.blurred .print-table { filter: blur(4px); opacity: 0.7; }
        </style>
    `;

    return `
        <!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Programa VMT - Vista Previa</title>
        <script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script>
