                <MobileAssignmentRow label={getValue('tesoros.p2.title') || 'Perlas Escondidas'}><CustomSelect options={lists['discursantes'] || []} value={getValue('tesoros.p2.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p2.main', val)} historyProvider={history} /></MobileAssignmentRow>
                <MobileAssignmentRow label={getValue('tesoros.p3.title') || '3. Lectura de la Biblia (3 min.)'}>
                    <div className="room-participants">
                        <div className="mobile-participant-pair"><span className="mobile-participant-pair__label">{roomMap.main}</span><div className="mobile-participant-pair__select"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.main') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.main', val)} historyProvider={history} /></div></div>
                        <div className="mobile-participant-pair"><span className="mobile-participant-pair__label">{roomMap.aux2}</span><div className="mobile-participant-pair__select"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.aux2') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.aux2', val)} historyProvider={history} /></div></div>
                        <div className="mobile-participant-pair"><span className="mobile-participant-pair__label">{roomMap.aux3}</span><div className="mobile-participant-pair__select"><CustomSelect options={lists['lectores'] || []} value={getValue('tesoros.p3.aux3') || ''} onChange={val => handleDataChange(selectedWeek, 'tesoros.p3.aux3', val)} historyProvider={history} /></div></div>
                    </div>
