                                {part.hasOwnProperty('lector') && (<MobileAssignmentRow label={`${part.titulo} (Lector)`}><CustomSelect options={lists['lectores_libro'] || []} value={getValue(`${pathPrefix}.lector`) || ''} onChange={val => handleDataChange(selectedWeek, `${pathPrefix}.lector`, val)} historyProvider={history} /></MobileAssignmentRow>)}
